<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowRight, Check, Eye, EyeOff } from 'lucide-vue-next'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../../stores/authStore'
const router=useRouter(); const auth=useAuthStore(); const name=ref(''); const email=ref(''); const password=ref(''); const confirm=ref(''); const show=ref(false); const agree=ref(false); const error=ref('')
const strength=computed(()=>password.value.length>=10?3:password.value.length>=6?2:password.value.length?1:0)
const submit=()=>{error.value='';if(password.value!==confirm.value){error.value='Passwords do not match.';return}if(!agree.value){error.value='Please accept the terms to continue.';return}const r=auth.register(name.value.trim(),email.value.trim(),password.value);if(r.ok)router.push('/');else error.value=r.message||'Could not create account.'}
</script>
